\draw[thick] (0,0)--(315:1);
\fill (315:1) circle (1.5pt);
\draw[->] (0.38,0) arc[start angle=0,end angle=315,radius=0.38];
\draw[->] (315:0.62) arc[start angle=315,end angle=360,radius=0.62];
\node at (-0.55,0.65) {$315^{\circ}$};
\node at (0.87,-0.25) {$45^{\circ}$};
\node[right] at (1.3,0) {$x$};
\node[above] at (0,1.3) {$y$};
\end{tikzpicture}
[/tikz]

$300^{\circ}=360^{\circ}-60^{\circ}$ lies in Q4, where the $x$-coordinate is positive and the $y$-coordinate is negative.

$\begin{aligned}x&=\cos 300^{\circ}\\&=\cos 60^{\circ}\\&=\frac{1}{2}\end{aligned}$

$\begin{aligned}y&=\sin 300^{\circ}\\&=-\sin 60^{\circ}\\&=-\frac{\sqrt{3}}{2}\end{aligned}$

$P=\left(\frac{1}{2},-\frac{\sqrt{3}}{2}\right)$

[tikz]
\begin{tikzpicture}[x=20mm,y=20mm,every node/.style={font=\fontsize{10}{12}\selectfont,text=black},draw=black]
