\draw (0,0) circle (1);
\coordinate (P) at (300:1);
\draw[thick] (0,0)--(P);
\draw[dashed] (P)--(0.5,0);
\draw (0.5,-0.09)--(0.41,-0.09)--(0.41,0);
\fill (P) circle (1.5pt);
\draw[->] (0.35,0) arc[start angle=0,end angle=300,radius=0.35];
\draw[->] (300:0.62) arc[start angle=300,end angle=360,radius=0.62];
\node at (-0.55,0.65) {$300^{\circ}$};
\node at (0.85,-0.4) {$60^{\circ}$};
\node[below right] at (P) {$P$};
\node[right] at (1.3,0) {$x$};
\node[above] at (0,1.3) {$y$};
\end{tikzpicture}
[/tikz]

